"""
views/empty_view.py — placeholder shown in the content pane
when no VM has been selected yet.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw
from .svg_assets import make_shield_image


class EmptyView(Gtk.Box):
    def __init__(self):
        super().__init__(orientation=Gtk.Orientation.VERTICAL)

        header = Adw.HeaderBar()
        header.set_show_end_title_buttons(True)
        self.append(header)

        # Centre box
        centre = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        centre.set_valign(Gtk.Align.CENTER)
        centre.set_halign(Gtk.Align.CENTER)
        centre.set_vexpand(True)

        # BulwarkOS shield — #546ac1 blue, 96px
        shield = make_shield_image(color="#546ac1", pixel_size=96)
        shield.set_halign(Gtk.Align.CENTER)
        centre.append(shield)

        title = Gtk.Label(label="BulwarkOS")
        title.add_css_class("title-1")
        centre.append(title)

        sub = Gtk.Label(
            label="Select a VM from the sidebar to view its controls and status."
        )
        sub.add_css_class("body")
        sub.add_css_class("dim-label")
        sub.set_justify(Gtk.Justification.CENTER)
        sub.set_wrap(True)
        centre.append(sub)

        self.append(centre)
